import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";
import { Toaster } from "sonner";
import "@/App.css";
import { AuthProvider, useAuth } from "@/lib/AuthContext";
import { NotificationProvider } from "@/lib/NotificationContext";
import Navbar from "@/components/Navbar";
import Home from "@/pages/Home";
import Login from "@/pages/Login";
import Register from "@/pages/Register";
import AuctionDetail from "@/pages/AuctionDetail";
import BuyerDashboard from "@/pages/BuyerDashboard";
import MyProducts from "@/pages/MyProducts";
import ProductDetails from "@/pages/ProductDetails";
import PaymentPage from "@/pages/PaymentPage";
import ReceiptPage from "@/pages/ReceiptPage";
import SellerDashboard from "@/pages/SellerDashboard";

function Protected({ children, role }) {
  const { user, ready } = useAuth();
  if (!ready) return null;
  if (!user) return <Navigate to="/login" replace />;
  if (role && user.role !== role) return <Navigate to="/" replace />;
  return children;
}

function Shell() {
  return (
    <div className="min-h-screen grain">
      <Navbar />
      <main className="pb-24">
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/login" element={<Login />} />
          <Route path="/register" element={<Register />} />
          <Route path="/auction/:id" element={<AuctionDetail />} />
          <Route
            path="/dashboard"
            element={<Protected role="buyer"><BuyerDashboard /></Protected>}
          />
          <Route
            path="/my-products"
            element={<Protected role="buyer"><MyProducts /></Protected>}
          />
          <Route
            path="/product/:id"
            element={<Protected role="buyer"><ProductDetails /></Protected>}
          />
          <Route
            path="/pay/:id"
            element={<Protected role="buyer"><PaymentPage /></Protected>}
          />
          <Route
            path="/receipt/:id"
            element={<Protected role="buyer"><ReceiptPage /></Protected>}
          />
          <Route
            path="/seller"
            element={<Protected role="seller"><SellerDashboard /></Protected>}
          />
        </Routes>
      </main>
      <Toaster position="top-right" richColors />
    </div>
  );
}

export default function App() {
  return (
    <BrowserRouter>
      <AuthProvider>
        <NotificationProvider>
          <Shell />
        </NotificationProvider>
      </AuthProvider>
    </BrowserRouter>
  );
}
