import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { api } from "@/lib/api";
import { useAuth } from "@/lib/AuthContext";
import { useNotifications } from "@/lib/NotificationContext";
import { inr, endsIn, timeAgo } from "@/lib/format";
import { Bell, Package, Trophy, Activity } from "lucide-react";

function Stat({ label, value, icon: Icon }) {
  return (
    <div className="rounded-2xl border border-border bg-card p-5 hover-lift">
      <div className="flex items-center justify-between text-muted-foreground text-xs uppercase tracking-widest">
        <span>{label}</span>
        <Icon size={16} className="text-accent"/>
      </div>
      <div className="serif text-3xl mt-2">{value}</div>
    </div>
  );
}

export default function BuyerDashboard() {
  const { user } = useAuth();
  const { items, unread } = useNotifications();
  const [myBids, setMyBids] = useState([]);
  const [won, setWon] = useState([]);

  useEffect(() => {
    api.get("/bids/my").then((r) => setMyBids(r.data));
    api.get("/my-products").then((r) => setWon(r.data));
  }, []);

  // Group by product to show one row per auction with best (own) bid
  const active = (() => {
    const map = new Map();
    for (const b of myBids) {
      const key = b.product.id;
      if (!map.has(key)) map.set(key, { product: b.product, myTop: b.bid });
      else if (b.bid.amount > map.get(key).myTop.amount) map.get(key).myTop = b.bid;
    }
    return [...map.values()].filter((r) => r.product.status === "active");
  })();

  return (
    <div className="max-w-7xl mx-auto px-6 lg:px-10 pt-10" data-testid="buyer-dashboard">
      <div className="fade-up">
        <div className="text-[11px] uppercase tracking-[0.3em] text-accent">Welcome</div>
        <h1 className="serif text-4xl md:text-5xl mt-2">{user?.name?.split(" ")[0] || "Bidder"}, here's the room.</h1>
        <p className="text-muted-foreground mt-3 max-w-xl">
          Track live bids, respond to outbid alerts, and settle winnings — all in one glance.
        </p>
      </div>

      <div className="grid md:grid-cols-4 gap-4 mt-10">
        <Stat label="Active bids" value={active.length} icon={Activity}/>
        <Stat label="Auctions won" value={won.length} icon={Trophy}/>
        <Stat label="Unread alerts" value={unread} icon={Bell}/>
        <Stat label="Awaiting payment" value={won.filter(w=>!w.payment).length} icon={Package}/>
      </div>

      <section className="mt-12 grid lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 rounded-2xl border border-border bg-card p-6">
          <div className="flex items-center justify-between">
            <h2 className="serif text-2xl">Your active bids</h2>
            <Link to="/" className="text-sm text-accent hover:underline">Browse more</Link>
          </div>
          <div className="mt-5 divide-y divide-border">
            {active.length === 0 && (
              <div className="py-10 text-center text-sm text-muted-foreground">
                You haven't placed any bids yet.
              </div>
            )}
            {active.map((row) => {
              // If my top bid equals the auction's current_price, I'm still leading
              const isLeading = Number(row.myTop.amount) >= Number(row.product.current_price);
              return (
                <Link
                  key={row.product.id}
                  to={`/auction/${row.product.id}`}
                  className="flex items-center gap-4 py-4 group"
                  data-testid={`active-bid-${row.product.id}`}
                >
                  <div className="w-16 h-16 rounded-lg overflow-hidden bg-muted shrink-0">
                    {row.product.image_url && <img src={row.product.image_url} alt="" className="w-full h-full object-cover"/>}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="serif text-lg truncate">{row.product.name}</div>
                    <div className="text-xs text-muted-foreground">
                      Your bid: {inr(row.myTop.amount)} · Highest: {inr(row.product.current_price)} · Ends in {endsIn(row.product.end_time)}
                    </div>
                  </div>
                  <div className={`text-[11px] uppercase tracking-widest px-2.5 py-1 rounded-full ${isLeading ? "bg-accent/10 text-accent" : "bg-destructive/10 text-destructive"}`}>
                    {isLeading ? "Leading" : "Outbid"}
                  </div>
                </Link>
              );
            })}
          </div>
        </div>

        <div className="rounded-2xl border border-border bg-card p-6">
          <h2 className="serif text-2xl">Recent alerts</h2>
          <div className="mt-5 space-y-4">
            {items.slice(0, 5).map((n) => (
              <div key={n.id} className="text-sm">
                <div className="font-medium leading-snug">{n.title}</div>
                <div className="text-xs text-muted-foreground mt-0.5 leading-relaxed">{n.message}</div>
                <div className="text-[11px] text-muted-foreground mt-1">{timeAgo(n.created_at)}</div>
              </div>
            ))}
            {items.length === 0 && <div className="text-sm text-muted-foreground">No alerts yet.</div>}
          </div>
        </div>
      </section>
    </div>
  );
}
