import axios from "axios";

// When the React app is served by the same Node server, BACKEND_URL is empty (relative paths).
// When developing separately, set REACT_APP_BACKEND_URL to the Node server URL.
export const BACKEND_URL = process.env.REACT_APP_BACKEND_URL || "";
export const API = `${BACKEND_URL}/api`;

export const api = axios.create({ baseURL: API });

api.interceptors.request.use((config) => {
  const t = localStorage.getItem("token");
  if (t) config.headers.Authorization = `Bearer ${t}`;
  return config;
});

export const SOCKET_URL = BACKEND_URL || undefined; // undefined lets socket.io use same origin
