import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { api } from "@/lib/api";
import { inr, fullDate } from "@/lib/format";
import { Button } from "@/components/ui/button";
import { PackageOpen, CheckCircle2, Truck, CreditCard, FileText, Eye } from "lucide-react";

function statusChip(paid) {
  const cls = paid
    ? "bg-accent/10 text-accent"
    : "bg-destructive/10 text-destructive";
  return (
    <span className={`text-[10px] uppercase tracking-widest px-2 py-1 rounded-full ${cls}`}>
      {paid ? "Paid" : "Payment pending"}
    </span>
  );
}

export default function MyProducts() {
  const [items, setItems] = useState(null);

  useEffect(() => {
    api.get("/my-products").then((r) => setItems(r.data));
  }, []);

  if (items === null) return <div className="max-w-6xl mx-auto px-6 py-16">Loading...</div>;

  return (
    <div className="max-w-7xl mx-auto px-6 lg:px-10 pt-10" data-testid="my-products-page">
      <div className="fade-up">
        <div className="text-[11px] uppercase tracking-[0.3em] text-accent">Your winnings</div>
        <h1 className="serif text-4xl md:text-5xl mt-2">My Products</h1>
        <p className="text-muted-foreground mt-3 max-w-xl">
          Auctions you've won. Complete payment and track delivery.
        </p>
      </div>

      {items.length === 0 && (
        <div className="mt-16 rounded-3xl border border-dashed border-border bg-card p-16 text-center fade-up">
          <div className="mx-auto w-16 h-16 rounded-full bg-muted grid place-items-center mb-4">
            <PackageOpen size={26} className="text-muted-foreground"/>
          </div>
          <div className="serif text-2xl">You haven't won any auctions yet.</div>
          <p className="text-sm text-muted-foreground mt-2">Place your first bid to start collecting.</p>
          <Link to="/">
            <Button className="mt-6 rounded-full" data-testid="browse-auctions-btn">Browse auctions</Button>
          </Link>
        </div>
      )}

      <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6 mt-10">
        {items.map((row, i) => {
          const p = row.product;
          const paid = row.payment?.status === "completed";
          return (
            <div key={p.id} className="rounded-2xl border border-border bg-card overflow-hidden hover-lift fade-up" style={{animationDelay: `${i*40}ms`}} data-testid={`won-item-${p.id}`}>
              <div className="aspect-[4/3] bg-muted relative">
                {p.image_url && <img src={p.image_url} alt={p.name} className="w-full h-full object-cover"/>}
                <div className="absolute top-3 left-3">{statusChip(paid)}</div>
              </div>
              <div className="p-5">
                <div className="text-[10px] uppercase tracking-widest text-muted-foreground">{p.category_name || p.category}</div>
                <div className="serif text-xl mt-1 truncate">{p.name}</div>
                <div className="text-xs text-muted-foreground mt-1">Sold by {p.seller_name}</div>

                <div className="mt-4 grid grid-cols-2 gap-2 text-xs">
                  <div>
                    <div className="text-muted-foreground">Winning bid</div>
                    <div className="serif text-lg text-accent">{inr(p.final_price ?? p.current_price)}</div>
                  </div>
                  <div>
                    <div className="text-muted-foreground">Ended</div>
                    <div className="text-sm">{fullDate(p.end_time)}</div>                  </div>
                </div>

                <div className="mt-3 flex items-center gap-2 text-xs text-muted-foreground">
                  <Truck size={13}/> Delivery: <span className="text-foreground">{row.delivery_status}</span>
                </div>

                <div className="mt-5 flex flex-wrap gap-2">
                  <Link to={`/product/${p.id}`} className="flex-1">
                    <Button variant="outline" className="w-full rounded-full" data-testid={`view-details-${p.id}`}>
                      <Eye size={14} className="mr-1.5"/> Details
                    </Button>
                  </Link>
                  {!paid && (
                    <Link to={`/pay/${p.id}`} className="flex-1">
                      <Button className="w-full rounded-full" data-testid={`pay-now-${p.id}`}>
                        <CreditCard size={14} className="mr-1.5"/> Pay Now
                      </Button>
                    </Link>
                  )}
                  {paid && (
                    <Link to={`/receipt/${p.id}`} className="flex-1">
                      <Button variant="outline" className="w-full rounded-full" data-testid={`view-receipt-${p.id}`}>
                        <FileText size={14} className="mr-1.5"/> Receipt
                      </Button>
                    </Link>
                  )}
                </div>

                {paid && (
                  <div className="mt-3 inline-flex items-center gap-1.5 text-xs text-accent">
                    <CheckCircle2 size={13}/> Payment Completed
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
