import { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import { api } from "@/lib/api";
import { inr, fullDate } from "@/lib/format";
import { Button } from "@/components/ui/button";
import { ArrowLeft, CreditCard, FileText, Truck } from "lucide-react";

export default function ProductDetails() {
  const { id } = useParams();
  const [data, setData] = useState(null);
  const [payment, setPayment] = useState(null);

  useEffect(() => {
    (async () => {
      const { data: p } = await api.get(`/products/${id}`);
      setData(p);
      try {
        const { data: pay } = await api.get(`/payments/product/${id}`);
        setPayment(pay.payment);
      } catch (_) { setPayment(null); }
    })();
  }, [id]);

  if (!data) return <div className="max-w-4xl mx-auto px-6 py-16">Loading...</div>;

  return (
    <div className="max-w-5xl mx-auto px-6 lg:px-10 pt-8" data-testid="product-details-page">
      <Link to="/my-products" className="inline-flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground mb-6">
        <ArrowLeft size={14}/> Back to My Products
      </Link>

      <div className="grid lg:grid-cols-12 gap-8">
        <div className="lg:col-span-7 rounded-2xl overflow-hidden border border-border bg-card">
          {data.image_url && <img src={data.image_url} alt={data.name} className="w-full aspect-[4/3] object-cover"/>}
        </div>
        <div className="lg:col-span-5">
          <div className="text-[11px] uppercase tracking-[0.3em] text-accent">{data.category_name || data.category}</div>
          <h1 className="serif text-4xl mt-2">{data.name}</h1>
          <p className="text-muted-foreground mt-3 leading-relaxed">{data.description}</p>

          <div className="mt-6 space-y-3 text-sm">
            <div className="flex justify-between border-b border-border pb-3">
              <span className="text-muted-foreground">Seller</span>
              <span>{data.seller_name}</span>
            </div>
            <div className="flex justify-between border-b border-border pb-3">
              <span className="text-muted-foreground">Winning bid</span>
              <span className="serif text-xl text-accent">{inr(data.final_price ?? data.current_price)}</span>
            </div>
            <div className="flex justify-between border-b border-border pb-3">
              <span className="text-muted-foreground">Auction start</span>
              <span>{fullDate(data.start_time)}</span>
            </div>
            <div className="flex justify-between border-b border-border pb-3">
              <span className="text-muted-foreground">Auction end</span>
              <span>{fullDate(data.end_time)}</span>
            </div>
            <div className="flex justify-between border-b border-border pb-3">
              <span className="text-muted-foreground">Payment status</span>
              <span className={payment ? "text-accent" : "text-destructive"}>{payment ? "Paid" : "Pending"}</span>
            </div>
            <div className="flex justify-between items-center border-b border-border pb-3">
              <span className="text-muted-foreground inline-flex items-center gap-1.5"><Truck size={13}/> Delivery</span>
              <span>{payment ? "Preparing shipment" : "Awaiting payment"}</span>
            </div>

            {payment && (
              <div className="rounded-lg bg-muted/60 p-4 mt-4">
                <div className="text-[10px] uppercase tracking-widest text-muted-foreground">Transaction</div>
                <div className="font-mono text-sm mt-1" data-testid="transaction-ref">{payment.transaction_ref}</div>
                <div className="text-xs text-muted-foreground mt-1">{fullDate(payment.created_at)}</div>
              </div>
            )}
          </div>

          <div className="mt-6 flex gap-3">
            {!payment && (
              <Link to={`/pay/${id}`} className="flex-1">
                <Button className="w-full rounded-full h-11" data-testid="details-pay-btn"><CreditCard size={15} className="mr-1.5"/> Pay Now</Button>
              </Link>
            )}
            {payment && (
              <Link to={`/receipt/${id}`} className="flex-1">
                <Button variant="outline" className="w-full rounded-full h-11" data-testid="details-receipt-btn"><FileText size={15} className="mr-1.5"/> View Receipt</Button>
              </Link>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
