import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "@/lib/AuthContext";
import { toast } from "sonner";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";

export default function Register() {
  const { register } = useAuth();
  const nav = useNavigate();
  const [form, setForm] = useState({ name: "", email: "", password: "", phone: "", role: "buyer" });
  const [busy, setBusy] = useState(false);

  const upd = (k, v) => setForm((f) => ({ ...f, [k]: v }));

  const submit = async (e) => {
    e.preventDefault();
    setBusy(true);
    try {
      const u = await register(form);
      toast.success(`Welcome, ${u.name}`);
      nav(u.role === "seller" ? "/seller" : "/dashboard");
    } catch (err) {
      toast.error(err?.response?.data?.detail || "Registration failed");
    } finally { setBusy(false); }
  };

  return (
    <div className="max-w-md mx-auto px-6 py-20 fade-up">
      <div className="text-[11px] uppercase tracking-[0.3em] text-accent">Join</div>
      <h1 className="serif text-4xl mt-2">Create account</h1>

      <form onSubmit={submit} className="space-y-4 mt-8" data-testid="register-form">
        <div>
          <Label>Full name</Label>
          <Input value={form.name} onChange={(e)=>upd("name", e.target.value)} required data-testid="register-name"/>
        </div>
        <div>
          <Label>Email</Label>
          <Input type="email" value={form.email} onChange={(e)=>upd("email", e.target.value)} required data-testid="register-email"/>
        </div>
        <div>
          <Label>Password</Label>
          <Input type="password" value={form.password} onChange={(e)=>upd("password", e.target.value)} minLength={6} required data-testid="register-password"/>
        </div>
        <div>
          <Label>Phone (optional)</Label>
          <Input value={form.phone} onChange={(e)=>upd("phone", e.target.value)} data-testid="register-phone"/>
        </div>
        <div>
          <Label>Role</Label>
          <RadioGroup value={form.role} onValueChange={(v)=>upd("role", v)} className="grid grid-cols-2 gap-3 mt-2">
            <label className={`border rounded-lg p-3 flex items-center gap-2 cursor-pointer ${form.role==="buyer"?"border-accent bg-accent/5":"border-border"}`}>
              <RadioGroupItem value="buyer" data-testid="role-buyer"/> <span>Buyer</span>
            </label>
            <label className={`border rounded-lg p-3 flex items-center gap-2 cursor-pointer ${form.role==="seller"?"border-accent bg-accent/5":"border-border"}`}>
              <RadioGroupItem value="seller" data-testid="role-seller"/> <span>Seller</span>
            </label>
          </RadioGroup>
        </div>

        <Button type="submit" disabled={busy} className="w-full rounded-full h-11" data-testid="register-submit">
          {busy ? "Creating..." : "Create account"}
        </Button>
      </form>

      <div className="mt-6 text-sm text-muted-foreground">
        Already have an account? <Link className="text-accent hover:underline" to="/login">Sign in</Link>
      </div>
    </div>
  );
}
