import { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import { api } from "@/lib/api";
import { useAuth } from "@/lib/AuthContext";
import { toast } from "sonner";
import { inr, timeAgo, endsIn, fullDate } from "@/lib/format";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Gavel, ArrowLeft, Clock } from "lucide-react";

export default function AuctionDetail() {
  const { id } = useParams();
  const { user } = useAuth();
  const [product, setProduct] = useState(null);
  const [amount, setAmount] = useState("");
  const [busy, setBusy] = useState(false);
  const [tick, setTick] = useState(0);

  const load = async () => {
    const { data } = await api.get(`/products/${id}`);
    setProduct(data);
    if (!amount) setAmount(String(Number(data.current_price) + Number(data.min_increment)));
  };

  useEffect(() => { load(); }, [id]);
  useEffect(() => {
    const t = setInterval(() => setTick((n) => n + 1), 3000);
    return () => clearInterval(t);
  }, []);
  useEffect(() => { if (tick > 0) load(); /* auto refresh */ }, [tick]);

  const placeBid = async (e) => {
    e.preventDefault();
    if (!user) { toast.error("Please login to place a bid."); return; }
    if (user.role !== "buyer") { toast.error("Only buyers can place bids"); return; }
    setBusy(true);
    try {
      await api.post("/bids", { product_id: Number(id), b_price: Number(amount) });
      toast.success("Bid Placed Successfully");
      await load();
    } catch (err) {
      toast.error(err?.response?.data?.message || err?.response?.data?.detail || "Bid failed");
    } finally { setBusy(false); }
  };

  if (!product) return <div className="max-w-6xl mx-auto px-6 py-16">Loading...</div>;

  const ended = new Date(product.end_time).getTime() <= Date.now();
  const minValid = Number(product.current_price) + Number(product.min_increment);

  return (
    <div className="max-w-6xl mx-auto px-6 lg:px-10 pt-8" data-testid="auction-detail">
      <Link to="/" className="inline-flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground mb-6">
        <ArrowLeft size={14}/> Back to auctions
      </Link>

      <div className="grid lg:grid-cols-12 gap-8">
        <div className="lg:col-span-7">
          <div className="rounded-2xl overflow-hidden border border-border bg-card">
            {product.image_url ? (
              <img src={product.image_url} alt={product.name} className="w-full aspect-[4/3] object-cover" />
            ) : (
              <div className="aspect-[4/3] grid place-items-center bg-muted"><Gavel size={40} /></div>
            )}
          </div>
          <div className="mt-6">
            <div className="text-[11px] uppercase tracking-[0.3em] text-accent">{product.category_name || product.category}</div>
            <h1 className="serif text-4xl md:text-5xl mt-2">{product.name}</h1>
            <p className="text-muted-foreground mt-4 leading-relaxed">{product.description}</p>
            <div className="mt-6 text-sm text-muted-foreground">Seller: <span className="text-foreground">{product.seller_name}</span></div>
          </div>
        </div>

        <div className="lg:col-span-5">
          <div className="sticky top-24 rounded-2xl border border-border bg-card p-6">
            <div className="flex items-center justify-between text-xs text-muted-foreground">
              <span className="uppercase tracking-widest">Current bid</span>
              <span className="inline-flex items-center gap-1.5">
                <Clock size={12} className="text-accent"/> {ended ? "Ended" : `Ends in ${endsIn(product.end_time)}`}
              </span>
            </div>
            <div className="serif text-5xl text-accent mt-2" data-testid="current-bid">{inr(product.current_price)}</div>
            <div className="text-xs text-muted-foreground mt-1">{product.bid_count} bids · min next {inr(minValid)}</div>

            {!ended && user?.role === "buyer" && (
              <form onSubmit={placeBid} className="mt-6 space-y-3" data-testid="bid-form">
                <Input
                  type="number"
                  step="1"
                  min={minValid}
                  value={amount}
                  onChange={(e)=>setAmount(e.target.value)}
                  placeholder={`≥ ${minValid}`}
                  data-testid="bid-amount"
                />
                <Button type="submit" disabled={busy} className="w-full rounded-full h-11" data-testid="bid-submit">
                  {busy ? "Placing..." : "Place bid"}
                </Button>
              </form>
            )}
            {!user && <div className="mt-6 text-sm text-muted-foreground">Sign in as a buyer to place bids.</div>}
            {user?.role === "seller" && <div className="mt-6 text-sm text-muted-foreground">Sellers cannot bid.</div>}
            {ended && <div className="mt-6 text-sm text-muted-foreground">This auction has ended.</div>}

            <div className="mt-8">
              <div className="text-[11px] uppercase tracking-widest text-muted-foreground mb-3">Bid history</div>
              <div className="space-y-2 max-h-64 overflow-y-auto pr-1">
                {product.bids.length === 0 && <div className="text-sm text-muted-foreground">No bids yet.</div>}
                {product.bids.map((b, i) => (
                  <div key={b.id} className="flex items-center justify-between text-sm py-2 border-b border-border last:border-0" data-testid={`bid-row-${i}`}>
                    <div>
                      <div className="font-medium">{b.buyer_name}</div>
                      <div className="text-xs text-muted-foreground">{timeAgo(b.created_at)}</div>
                    </div>
                    <div className={`serif text-lg ${i===0 ? "text-accent" : ""}`}>{inr(b.amount)}</div>
                  </div>
                ))}
              </div>
            </div>

            <div className="mt-6 text-xs text-muted-foreground grid grid-cols-2 gap-3 pt-6 border-t border-border">
              <div>Starts<br/><span className="text-foreground">{fullDate(product.start_time)}</span></div>
              <div>Ends<br/><span className="text-foreground">{fullDate(product.end_time)}</span></div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
