import { Link } from "react-router-dom";
import { useNotifications } from "@/lib/NotificationContext";
import { timeAgo } from "@/lib/format";
import { AlertTriangle, Trophy, CreditCard, BellRing, ExternalLink, Check } from "lucide-react";

function iconFor(type) {
  if (type === "outbid") return <AlertTriangle size={16} className="text-destructive" />;
  if (type === "winner") return <Trophy size={16} className="text-accent" />;
  if (type === "payment") return <CreditCard size={16} className="text-accent" />;
  return <BellRing size={16} />;
}

export default function NotificationList() {
  const { items, unread, markRead, markAllRead } = useNotifications();

  return (
    <div className="flex flex-col max-h-[70vh]" data-testid="notification-list">
      <div className="flex items-center justify-between px-4 py-3 border-b border-border">
        <div>
          <div className="serif text-lg leading-none">Notifications</div>
          <div className="text-xs text-muted-foreground mt-1">
            {unread > 0 ? `${unread} unread` : "All caught up"}
          </div>
        </div>
        {unread > 0 && (
          <button
            className="text-xs text-accent hover:underline"
            onClick={markAllRead}
            data-testid="mark-all-read"
          >
            Mark all read
          </button>
        )}
      </div>

      <div className="overflow-y-auto flex-1 min-h-[100px]">
        {items.length === 0 && (
          <div className="p-8 text-center text-sm text-muted-foreground">
            No notifications yet. You'll be alerted the moment someone outbids you.
          </div>
        )}
        {items.map((n) => (
          <div
            key={n.id}
            className={`slide-in-right px-4 py-3 border-b border-border last:border-b-0 flex gap-3 ${
              !n.is_read ? "bg-muted/40" : ""
            }`}
            data-testid={`notification-${n.type}`}
          >
            <div className="mt-0.5 shrink-0">{iconFor(n.type)}</div>
            <div className="flex-1 min-w-0">
              <div className="flex items-start justify-between gap-3">
                <div className="text-sm font-semibold leading-snug">{n.title}</div>
                {!n.is_read && <span className="w-1.5 h-1.5 rounded-full bg-accent mt-1.5 shrink-0" />}
              </div>
              <div className="text-xs text-muted-foreground mt-1 leading-relaxed">{n.message}</div>

              {n.type === "outbid" && n.data?.previous_bid != null && (
                <div className="mt-2 grid grid-cols-2 gap-2 text-xs">
                  <div className="rounded-md bg-background border border-border px-2 py-1.5">
                    <div className="text-[10px] uppercase tracking-wider text-muted-foreground">Your bid</div>
                    <div className="font-medium">₹{Number(n.data.previous_bid).toLocaleString("en-IN")}</div>
                  </div>
                  <div className="rounded-md bg-background border border-border px-2 py-1.5">
                    <div className="text-[10px] uppercase tracking-wider text-muted-foreground">Highest now</div>
                    <div className="font-medium text-accent">₹{Number(n.data.current_bid).toLocaleString("en-IN")}</div>
                  </div>
                </div>
              )}

              <div className="mt-2 flex items-center justify-between">
                <div className="text-[11px] text-muted-foreground">{timeAgo(n.created_at)}</div>
                <div className="flex items-center gap-2">
                  {!n.is_read && (
                    <button
                      className="text-[11px] text-muted-foreground hover:text-foreground inline-flex items-center gap-1"
                      onClick={() => markRead(n.id)}
                      data-testid={`mark-read-${n.id}`}
                    >
                      <Check size={12}/> Mark read
                    </button>
                  )}
                  {n.data?.product_id && (
                    <Link
                      to={`/auction/${n.data.product_id}`}
                      className="text-[11px] font-medium text-accent hover:underline inline-flex items-center gap-1"
                      onClick={() => markRead(n.id)}
                      data-testid={`view-auction-${n.id}`}
                    >
                      View Auction <ExternalLink size={12}/>
                    </Link>
                  )}
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
