import { createContext, useCallback, useContext, useEffect, useRef, useState } from "react";
import { io } from "socket.io-client";
import { api, SOCKET_URL } from "@/lib/api";
import { useAuth } from "@/lib/AuthContext";
import { toast } from "sonner";

const NotifCtx = createContext(null);

export function NotificationProvider({ children }) {
  const { user } = useAuth();
  const [items, setItems] = useState([]);
  const sockRef = useRef(null);

  const load = useCallback(async () => {
    if (!user) return;
    try {
      const { data } = await api.get("/notifications");
      setItems(Array.isArray(data) ? data : []);
    } catch (_) { /* ignore */ }
  }, [user]);

  useEffect(() => { load(); }, [load]);

  useEffect(() => {
    if (!user) return;
    const sock = SOCKET_URL ? io(SOCKET_URL) : io();
    sockRef.current = sock;
    sock.on("connect", () => sock.emit("joinUser", { userId: user.id, role: user.role }));
    sock.on("notification", (n) => {
      setItems((prev) => [n, ...prev]);
      if (n.type === "outbid") toast.error(n.title, { description: n.message, duration: 6000 });
      else if (n.type === "winner") toast.success(n.title, { description: n.message, duration: 6000 });
      else if (n.type === "payment") toast.success(n.title, { description: n.message });
      else toast(n.title || "Notification", { description: n.message });
    });
    return () => { try { sock.disconnect(); } catch (_) {} };
  }, [user]);

  const unread = items.filter((n) => !n.is_read).length;

  const markRead = async (id) => {
    setItems((prev) => prev.map((n) => (n.id === id ? { ...n, is_read: true } : n)));
    await api.post(`/notifications/${id}/read`).catch(() => {});
  };

  const markAllRead = async () => {
    setItems((prev) => prev.map((n) => ({ ...n, is_read: true })));
    await api.post(`/notifications/read-all`).catch(() => {});
  };

  return (
    <NotifCtx.Provider value={{ items, unread, refresh: load, markRead, markAllRead }}>
      {children}
    </NotifCtx.Provider>
  );
}

export const useNotifications = () => useContext(NotifCtx);
