import { useEffect, useState } from "react";
import { api } from "@/lib/api";
import { toast } from "sonner";
import { inr, endsIn } from "@/lib/format";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Label } from "@/components/ui/label";
import { Plus } from "lucide-react";

export default function SellerDashboard() {
  const [cats, setCats] = useState([]);
  const [products, setProducts] = useState([]);
  const [form, setForm] = useState({
    name: "", description: "", category_id: "", image_url: "",
    starting_price: "", min_increment: "1", start_time: "", end_time: "",
  });

  const loadProducts = () => api.get("/products").then((r) => setProducts(r.data));

  useEffect(() => {
    api.get("/categories").then((r) => setCats(r.data));
    loadProducts();
  }, []);

  const upd = (k, v) => setForm((f) => ({ ...f, [k]: v }));

  const submit = async (e) => {
    e.preventDefault();
    try {
      // Node expects local ISO-ish datetime strings; the datetime-local input value works
      await api.post("/products", {
        name: form.name,
        description: form.description,
        category_id: Number(form.category_id),
        image_url: form.image_url || null,
        starting_price: Number(form.starting_price),
        min_increment: Number(form.min_increment),
        start_time: form.start_time.replace("T", " ") + ":00",
        end_time: form.end_time.replace("T", " ") + ":00",
      });
      toast.success("Auction submitted for admin approval");
      setForm({ name:"", description:"", category_id:"", image_url:"", starting_price:"", min_increment:"1", start_time:"", end_time:"" });
      loadProducts();
    } catch (err) {
      toast.error(err?.response?.data?.message || err?.response?.data?.detail || "Failed");
    }
  };

  return (
    <div className="max-w-6xl mx-auto px-6 lg:px-10 pt-10 pb-16">
      <div className="fade-up">
        <div className="text-[11px] uppercase tracking-[0.3em] text-accent">Seller studio</div>
        <h1 className="serif text-4xl md:text-5xl mt-2">Create an auction</h1>
      </div>

      <form onSubmit={submit} className="mt-8 grid md:grid-cols-2 gap-4 rounded-2xl border border-border bg-card p-6" data-testid="create-auction-form">
        <div className="md:col-span-2">
          <Label>Name</Label>
          <Input value={form.name} onChange={(e)=>upd("name", e.target.value)} required/>
        </div>
        <div className="md:col-span-2">
          <Label>Description</Label>
          <Textarea rows={3} value={form.description} onChange={(e)=>upd("description", e.target.value)}/>
        </div>
        <div>
          <Label>Category</Label>
          <Select value={form.category} onValueChange={(v)=>upd("category", v)} required>
            <SelectTrigger><SelectValue placeholder="Select..."/></SelectTrigger>
            <SelectContent>
              {cats.map((c) => <SelectItem key={c} value={c}>{c}</SelectItem>)}
            </SelectContent>
          </Select>
        </div>
        <div>
          <Label>Image URL</Label>
          <Input value={form.image_url} onChange={(e)=>upd("image_url", e.target.value)} placeholder="https://..."/>
        </div>
        <div>
          <Label>Starting price (₹)</Label>
          <Input type="number" value={form.starting_price} onChange={(e)=>upd("starting_price", e.target.value)} required/>
        </div>
        <div>
          <Label>Min increment (₹)</Label>
          <Input type="number" value={form.min_increment} onChange={(e)=>upd("min_increment", e.target.value)} required/>
        </div>
        <div>
          <Label>Start</Label>
          <Input type="datetime-local" value={form.start_time} onChange={(e)=>upd("start_time", e.target.value)} required/>
        </div>
        <div>
          <Label>End</Label>
          <Input type="datetime-local" value={form.end_time} onChange={(e)=>upd("end_time", e.target.value)} required/>
        </div>
        <div className="md:col-span-2">
          <Button type="submit" className="rounded-full"><Plus size={14} className="mr-1.5"/> Create auction</Button>
        </div>
      </form>

      <h2 className="serif text-3xl mt-12">All auctions</h2>
      <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6 mt-6">
        {products.map((p) => (
          <div key={p.id} className="rounded-2xl border border-border bg-card overflow-hidden">
            <div className="aspect-[4/3] bg-muted">
              {p.image_url && <img src={p.image_url} alt={p.name} className="w-full h-full object-cover"/>}
            </div>
            <div className="p-4">
              <div className="serif text-lg truncate">{p.name}</div>
              <div className="text-xs text-muted-foreground">{p.status} · Ends in {endsIn(p.end_time)}</div>
              <div className="text-accent serif text-xl mt-1">{inr(p.current_price)}</div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
