import { useEffect, useState } from "react";
import { api } from "@/lib/api";
import ProductCard from "@/components/ProductCard";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Search } from "lucide-react";

export default function Home() {
  const [products, setProducts] = useState([]);
  const [cats, setCats] = useState([]);
  const [q, setQ] = useState("");
  const [category, setCategory] = useState("all");
  const [sort, setSort] = useState("ending_soon");

  useEffect(() => {
    api.get("/categories").then((r) => setCats(r.data));
  }, []);

  useEffect(() => {
    const params = {};
    if (q) params.search = q;
    if (category !== "all") params.category = category;
    if (sort) params.sortBy = sort;
    api.get("/products", { params }).then((r) => {
      // Only show approved/active auctions on the public home
      setProducts(r.data.filter((p) => p.status === "active" || p.status === "approved"));
    });
  }, [q, category, sort]);

  return (
    <div className="max-w-7xl mx-auto px-6 lg:px-10">
      {/* Hero */}
      <section className="pt-16 pb-12 fade-up">
        <div className="grid lg:grid-cols-12 gap-8 items-end">
          <div className="lg:col-span-8">
            <div className="text-[11px] uppercase tracking-[0.3em] text-accent mb-4">Live · Curated · Verified</div>
            <h1 className="serif text-5xl md:text-6xl lg:text-7xl leading-[1.02]">
              Bid on things worth<br/>
              <span className="italic">holding&nbsp;onto.</span>
            </h1>
            <p className="mt-6 text-muted-foreground max-w-xl leading-relaxed">
              Real-time auctions with instant outbid alerts. When someone beats your bid,
              you know before your coffee cools.
            </p>
          </div>
          <div className="lg:col-span-4 space-y-3 text-sm text-muted-foreground">
            <div className="flex justify-between border-t border-border pt-3">
              <span>Active lots</span><span className="font-medium text-foreground serif text-lg">{products.length}</span>
            </div>
            <div className="flex justify-between border-t border-border pt-3">
              <span>Response time</span><span className="font-medium text-foreground serif text-lg">Instant</span>
            </div>
            <div className="flex justify-between border-t border-border pt-3">
              <span>Currency</span><span className="font-medium text-foreground serif text-lg">INR ₹</span>
            </div>
          </div>
        </div>
      </section>

      {/* Filters */}
      <section className="flex flex-col md:flex-row gap-3 md:items-center md:justify-between py-6 border-y border-border">
        <div className="relative flex-1 max-w-md">
          <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
          <Input
            value={q}
            onChange={(e) => setQ(e.target.value)}
            placeholder="Search auctions..."
            className="pl-9 bg-background"
            data-testid="search-input"
          />
        </div>
        <div className="flex items-center gap-3">
          <Select value={category} onValueChange={setCategory}>
            <SelectTrigger className="w-[180px]" data-testid="category-filter"><SelectValue placeholder="Category"/></SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All categories</SelectItem>
              {cats.map((c) => <SelectItem key={c.category_id} value={String(c.category_id)}>{c.name}</SelectItem>)}
            </SelectContent>
          </Select>
          <Select value={sort} onValueChange={setSort}>
            <SelectTrigger className="w-[170px]" data-testid="sort-filter"><SelectValue placeholder="Sort"/></SelectTrigger>
            <SelectContent>
              <SelectItem value="ending_soon">Ending soon</SelectItem>
              <SelectItem value="price_asc">Price ↑</SelectItem>
              <SelectItem value="price_desc">Price ↓</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </section>

      {/* Grid */}
      <section className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mt-10">
        {products.map((p, i) => <ProductCard key={p.id} p={p} index={i} />)}
        {products.length === 0 && (
          <div className="col-span-full text-center py-16 text-muted-foreground">
            No auctions match your filters.
          </div>
        )}
      </section>
    </div>
  );
}
