import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "@/lib/AuthContext";
import { useNotifications } from "@/lib/NotificationContext";
import { Bell, Gavel, LogOut, Package, LayoutDashboard, Store } from "lucide-react";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import NotificationList from "@/components/NotificationList";

export default function Navbar() {
  const { user, logout } = useAuth();
  const nav = useNavigate();
  const notifications = useNotifications();
  const unread = notifications?.unread ?? 0;

  return (
    <header className="sticky top-0 z-40 backdrop-blur-md bg-background/80 border-b border-border" data-testid="navbar">
      <div className="max-w-7xl mx-auto px-6 lg:px-10 flex items-center justify-between h-16">
        <Link to="/" className="flex items-center gap-2 group" data-testid="brand-link">
          <div className="w-9 h-9 rounded-lg bg-foreground text-background grid place-items-center">
            <Gavel size={18} />
          </div>
          <div className="leading-tight">
            <div className="serif text-xl">Auctorium</div>
            <div className="text-[10px] uppercase tracking-[0.2em] text-muted-foreground">Live Auctions</div>
          </div>
        </Link>

        <nav className="flex items-center gap-1 md:gap-3">
          <Link to="/" className="px-3 py-2 text-sm hover:text-accent transition" data-testid="nav-browse">Browse</Link>
          {user?.role === "buyer" && (
            <>
              <Link to="/dashboard" className="hidden md:inline-flex items-center gap-1.5 px-3 py-2 text-sm hover:text-accent transition" data-testid="nav-dashboard">
                <LayoutDashboard size={15}/> Dashboard
              </Link>
              <Link to="/my-products" className="hidden md:inline-flex items-center gap-1.5 px-3 py-2 text-sm hover:text-accent transition" data-testid="nav-my-products">
                <Package size={15}/> My Products
              </Link>
            </>
          )}
          {user?.role === "seller" && (
            <Link to="/seller" className="hidden md:inline-flex items-center gap-1.5 px-3 py-2 text-sm hover:text-accent transition" data-testid="nav-seller">
              <Store size={15}/> Seller
            </Link>
          )}

          {user && (
            <Popover>
              <PopoverTrigger asChild>
                <button
                  aria-label="Notifications"
                  className="relative w-10 h-10 rounded-full grid place-items-center hover:bg-muted transition"
                  data-testid="notification-bell"
                >
                  <Bell size={18} />
                  {unread > 0 && (
                    <span className="absolute top-1.5 right-1.5 flex">
                      <span className="pulse-dot absolute inset-0 rounded-full bg-accent/70" />
                      <span className="relative w-2 h-2 rounded-full bg-accent" />
                    </span>
                  )}
                </button>
              </PopoverTrigger>
              <PopoverContent align="end" className="w-[380px] p-0 border-border" data-testid="notification-popover">
                <NotificationList />
              </PopoverContent>
            </Popover>
          )}

          {user ? (
            <div className="flex items-center gap-2 pl-2 ml-2 border-l border-border">
              <div className="hidden md:block text-right leading-tight">
                <div className="text-sm font-medium" data-testid="user-name">{user.name}</div>
                <div className="text-[10px] uppercase tracking-widest text-muted-foreground">{user.role}</div>
              </div>
              <button
                onClick={() => { logout(); nav("/"); }}
                className="w-9 h-9 rounded-full grid place-items-center hover:bg-muted transition"
                data-testid="logout-btn"
                aria-label="Logout"
              >
                <LogOut size={16} />
              </button>
            </div>
          ) : (
            <div className="flex items-center gap-2 pl-2">
              <Link to="/login" className="px-3 py-2 text-sm" data-testid="nav-login">Sign in</Link>
              <Link to="/register" className="px-4 py-2 text-sm rounded-full bg-foreground text-background hover:bg-foreground/90 transition" data-testid="nav-register">
                Join
              </Link>
            </div>
          )}
        </nav>
      </div>
    </header>
  );
}
