import { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import { api } from "@/lib/api";
import { inr, fullDate } from "@/lib/format";
import { Button } from "@/components/ui/button";
import { Printer, ArrowLeft, Gavel } from "lucide-react";

export default function ReceiptPage() {
  const { id } = useParams();
  const [data, setData] = useState(null);

  useEffect(() => {
    api.get(`/payments/product/${id}`).then((r) => setData(r.data));
  }, [id]);

  if (!data) return <div className="max-w-2xl mx-auto px-6 py-16">Loading...</div>;

  const { payment, product } = data;

  return (
    <div className="max-w-3xl mx-auto px-6 lg:px-10 py-10">
      <div className="flex items-center justify-between mb-6 no-print">
        <Link to="/my-products" className="inline-flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground">
          <ArrowLeft size={14}/> Back
        </Link>
        <Button onClick={() => window.print()} className="rounded-full" data-testid="print-receipt">
          <Printer size={14} className="mr-1.5"/> Download / Print
        </Button>
      </div>

      <div id="receipt-print" className="rounded-2xl border border-border bg-card p-10 fade-up" data-testid="receipt-content">
        <div className="flex items-center justify-between border-b border-border pb-6">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-lg bg-foreground text-background grid place-items-center">
              <Gavel size={18}/>
            </div>
            <div>
              <div className="serif text-2xl leading-none">Auctorium</div>
              <div className="text-[10px] uppercase tracking-widest text-muted-foreground mt-1">Payment Receipt</div>
            </div>
          </div>
          <div className="text-right text-xs text-muted-foreground">
            <div>Issued</div>
            <div className="text-foreground font-medium">{fullDate(payment.created_at)}</div>
          </div>
        </div>

        <div className="grid grid-cols-2 gap-6 mt-6 text-sm">
          <div>
            <div className="text-[10px] uppercase tracking-widest text-muted-foreground">Transaction ID</div>
            <div className="font-mono mt-1">{payment.transaction_ref}</div>
          </div>
          <div>
            <div className="text-[10px] uppercase tracking-widest text-muted-foreground">Method</div>
            <div className="mt-1 capitalize">{payment.method.replace("_", " ")}</div>
          </div>
          <div>
            <div className="text-[10px] uppercase tracking-widest text-muted-foreground">Product</div>
            <div className="mt-1">{product?.name}</div>
          </div>
          <div>
            <div className="text-[10px] uppercase tracking-widest text-muted-foreground">Status</div>
            <div className="mt-1 text-accent">Paid</div>
          </div>
        </div>

        <div className="mt-8 border-t border-border pt-6 space-y-2 text-sm">
          <div className="flex justify-between"><span className="text-muted-foreground">Winning bid</span><span>{inr(product?.final_price ?? product?.current_price ?? 0)}</span></div>
          <div className="flex justify-between"><span className="text-muted-foreground">Platform fee</span><span>{inr(payment.amount - (product?.final_price ?? product?.current_price ?? payment.amount))}</span></div>
          <div className="flex justify-between border-t border-border pt-3 mt-2">
            <span className="serif text-xl">Total paid</span>
            <span className="serif text-2xl text-accent">{inr(payment.amount)}</span>
          </div>
        </div>

        <div className="mt-10 text-[11px] text-muted-foreground border-t border-border pt-4 text-center">
          This is a mock receipt generated for demonstration purposes. Thank you for bidding with Auctorium.
        </div>
      </div>
    </div>
  );
}
