import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "@/lib/AuthContext";
import { toast } from "sonner";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";

export default function Login() {
  const { login } = useAuth();
  const nav = useNavigate();
  const [email, setEmail] = useState("buyer@auction.com");
  const [password, setPassword] = useState("Password@123");
  const [busy, setBusy] = useState(false);

  const submit = async (e) => {
    e.preventDefault();
    setBusy(true);
    try {
      const u = await login(email, password);
      toast.success(`Welcome back, ${u.name}`);
      nav(u.role === "seller" ? "/seller" : "/dashboard");
    } catch (err) {
      toast.error(err?.response?.data?.detail || "Login failed");
    } finally { setBusy(false); }
  };

  return (
    <div className="max-w-md mx-auto px-6 py-20 fade-up">
      <div className="text-[11px] uppercase tracking-[0.3em] text-accent">Members</div>
      <h1 className="serif text-4xl mt-2">Sign in</h1>
      <p className="text-sm text-muted-foreground mt-2">Bid, track, win. Start where you left off.</p>

      <form onSubmit={submit} className="space-y-4 mt-8" data-testid="login-form">
        <div>
          <Label htmlFor="email">Email</Label>
          <Input id="email" type="email" value={email} onChange={(e)=>setEmail(e.target.value)} required data-testid="login-email"/>
        </div>
        <div>
          <Label htmlFor="password">Password</Label>
          <Input id="password" type="password" value={password} onChange={(e)=>setPassword(e.target.value)} required data-testid="login-password"/>
        </div>
        <Button type="submit" disabled={busy} className="w-full rounded-full h-11" data-testid="login-submit">
          {busy ? "Signing in..." : "Sign in"}
        </Button>
      </form>

      <div className="text-xs text-muted-foreground mt-6 border-t border-border pt-4 space-y-1">
        <div>Buyer demo: <code>buyer@auction.com / Password@123</code></div>
        <div>Seller demo: <code>seller@auction.com / Password@123</code></div>
      </div>

      <div className="mt-6 text-sm text-muted-foreground">
        New here? <Link className="text-accent hover:underline" to="/register" data-testid="register-link">Create an account</Link>
      </div>
    </div>
  );
}
